contract LoanToken is Context, IERC20Metadata, Ownable {
  mapping(address => uint256) private _balances;

  mapping(address => mapping(address => uint256)) private _allowances;

  uint256 private _totalSupply;

  string private _name;
  string private _symbol;
  uint8 private constant _decimals = 18;
  uint256 public constant presaleReserve = 1_600_000_000 * (10 ** _decimals);
  uint256 public constant stakingReserve = 2_400_000_000 * (10 ** _decimals);
  uint256 public constant marketingReserve = 1_600_000_000 * (10 ** _decimals);
  uint256 public constant liquidityReserve = 800_000_000 * (10 ** _decimals);
  uint256 public constant projectFinanceReserve = 800_000_000 * (10 ** _decimals);
  uint256 public constant chainInventoryReserve = 800_000_000 * (10 ** _decimals);

  /**
   * @dev Contract constructor. 
   */
  constructor() {
    _name = 'LoanToken';
    _symbol = 'LOAN';
    _mint(0xE98b997f529F643Bc67F217B1270A0F7D7a0EcB2, presaleReserve); // 1
    _mint(0xf69DA7C57f3A887B16Af7F068ed2882aff620359, stakingReserve); // 3
    _mint(0x6470c4d86b062fF4e1030D5615c4B04cD78bF9Cf, marketingReserve);  //5
    _mint(0x24CDb8B705fBD6faBaf32f5Af16c4A23dB14f215, liquidityReserve); // 4
    _mint(0x4F14309C857AA274F2E6d7cB86b89F1FBdd21223, projectFinanceReserve); //6
    _mint(0xA4941d3586aA79a39A0C84c6cCFDD54Eae4D69ef, chainInventoryReserve); //7
  }

  /**
   * @dev Returns the name of the token.
   * @return The name of the token.
   */
  function name() public view virtual override returns (string memory) {
    return _name;
  }

  /**
   * @dev Returns the symbol of the token.
   * @return The symbol of the token.
   */
  function symbol() public view virtual override returns (string memory) {
    return _symbol;
  }

  /**
   * @dev Returns the number of decimals used for token display.
   * @return The number of decimals.
   */
  function decimals() public view virtual override returns (uint8) {
    return _decimals;
  }

  /**
   * @dev Returns the total supply of the token.
   * @return The total supply.
   */
  function totalSupply() public view virtual override returns (uint256) {
    return _totalSupply;
  }

  /**
   * @dev Returns the balance of the specified account.
   * @param account The address to check the balance for.
   * @return The balance of the account.
   */
  function balanceOf(address account) public view virtual override returns (uint256) {
    return _balances[account];
  }

  /**
   * @dev Transfers tokens from the caller to a specified recipient.
   * @param recipient The address to transfer tokens to.
   * @param amount The amount of tokens to transfer.
   * @return A boolean value indicating whether the transfer was successful.
   */
